{
  "results": [
    {
      "server": "crm",
      "tools": [
        {
          "tool_name": "crm__issue_soql_query",
          "description": "Run a SOQL query against the CRM. Returns matching records. Relationship traversal (Account.Name) and subqueries are not supported.",
          "score": 2.8705739974975586,
          "input_schema": {
            "type": "object",
            "properties": {
              "query": {
                "type": "string",
                "description": "A SOQL statement, e.g. SELECT Id, Subject FROM Case LIMIT 10"
              }
            },
            "required": [
              "query"
            ]
          }
        },
        {
          "tool_name": "crm__get_schema",
          "description": "List the fields available on an object, and the objects available if omitted.",
          "score": 1.6827452182769775,
          "input_schema": {
            "type": "object",
            "properties": {
              "object": {
                "type": "string",
                "description": "Object API name; omit to list all objects."
              }
            }
          }
        },
        {
          "tool_name": "crm__issue_sosl_query",
          "description": "Full-text search across text fields of an object, in the style of SOSL FIND.",
          "score": 0.919001042842865,
          "input_schema": {
            "type": "object",
            "properties": {
              "search_term": {
                "type": "string",
                "description": "Text to search for."
              },
              "object": {
                "type": "string",
                "description": "Object to search, e.g. Case, Product2, Knowledge__kav."
              },
              "limit": {
                "type": "integer",
                "description": "Max records (default 20)."
              }
            },
            "required": [
              "search_term"
            ]
          }
        },
        {
          "tool_name": "crm__search_knowledge_articles",
          "description": "Search the knowledge base for articles matching a query.",
          "score": 0.12329073250293732,
          "input_schema": {
            "type": "object",
            "properties": {
              "search_term": {
                "type": "string"
              },
              "limit": {
                "type": "integer"
              }
            },
            "required": [
              "search_term"
            ]
          }
        },
        {
          "tool_name": "crm__respond",
          "description": "Submit your final answer. Give the answer only — an Id, a value, or 'None' if the question cannot be answered from the data. Call this exactly once, at the end.",
          "score": 0.1162005364894867,
          "input_schema": {
            "type": "object",
            "properties": {
              "answer": {
                "type": "string",
                "description": "The final answer."
              }
            },
            "required": [
              "answer"
            ]
          }
        }
      ]
    }
  ],
  "total_hidden_tools": 5,
  "status": "ready",
  "note": null
}
